26	/// `npm view` arguments for one package version. Auth comes from the same place it does for the publish: the
27	/// environment and the user's own `.npmrc` reach both children alike, and that temporary config, which only the
28	/// publish child would otherwise see, is passed here too, because a restricted package answers an anonymous `view` with 404.
29	pub(super) fn npm_view_args(
30	    spec: &str,
31	    repository_only: bool,
32	    registry: Option<&str>,
33	    userconfig: Option<&str>,
34	) -> Vec<String> {
35	    let mut args = vec!["view".to_owned(), spec.to_owned()];
36	    if repository_only {
37	        args.push("repository".to_owned());
38	    }
39	    args.extend(["--json".to_owned(), "--fetch-retries=0".to_owned()]);
40	    if let Some(registry) = registry {
41	        args.extend(["--registry".to_owned(), registry.to_owned()]);
42	    }
43	    if let Some(userconfig) = userconfig {
44	        args.extend(["--userconfig".to_owned(), userconfig.to_owned()]);
45	    }
46	    args
47	}
