49	pub(super) fn npm_publisher_environment<'a>(
50	    program: &str,
51	    token: Option<&'a str>,
52	    config: Option<&'a str>,
53	) -> Vec<(&'static str, &'a str)> {
54	    let mut env = Vec::new();
55	    if let Some(token) = token {
56	        env.push(("NPM_TOKEN", token));
57	        if program == "bun" {
58	            env.push(("NPM_CONFIG_TOKEN", token));
59	        }
60	    }
61	    if let Some(config) = config {
62	        env.push(("NPM_CONFIG_USERCONFIG", config));
63	    }
64	    env
65	}
