67	/// The code npm gives a registry 404 for a package or a version.
68	pub(super) const NPM_NOT_FOUND_CODE: &str = "E404";
69	
70	/// Only npm's own `E404` code proves absence, never text around it; any other failure is a retried `CommandFailed`.
71	pub(super) fn classify_npm_view(output: &CommandOutput, version: &Version) -> Attempt<ProviderObservationV1> {
72	    if output.success() {
73	        return if output.stdout_trimmed().is_empty() {
74	            transient(ProviderIndeterminateCause::MalformedResponse, None)
75	        } else {
76	            settled(ProviderObservationV1::Exact {
77	                evidence: ProviderEvidenceV1::RegistryVersion {
78	                    version: version.clone(),
79	                    checksum: None,
80	                    yanked: None,
81	                },
82	            })
83	        };
84	    }
85	    let code = if output.stdout_trimmed().is_empty() {
86	        npm_stderr_code(&output.stderr)
87	    } else {
88	        npm_error_code(&output.stdout)
89	    };
90	    if code.as_deref() == Some(NPM_NOT_FOUND_CODE) {
91	        return settled(ProviderObservationV1::Absent);
92	    }
93	    transient(ProviderIndeterminateCause::CommandFailed, None)
94	}
