96	/// The repository URL in `npm view <spec> repository --json`: a string, or an object with a `url`.
97	pub(super) fn npm_view_repository(stdout: &str) -> Option<String> {
98	    let value: serde_json::Value = serde_json::from_str(stdout.trim()).ok()?;
99	    match value {
100	        serde_json::Value::String(url) => Some(url),
101	        serde_json::Value::Object(map) => map.get("url")?.as_str().map(str::to_owned),
102	        _ => None,
103	    }
104	    .filter(|url| !url.is_empty())
105	}
