107	/// The `error.code` of the JSON error body `npm --json` prints to stdout on failure.
108	pub(super) fn npm_error_code(stdout: &str) -> Option<String> {
109	    let body: serde_json::Value = serde_json::from_str(stdout.trim()).ok()?;
110	    body.get("error")?.get("code")?.as_str().map(str::to_owned)
111	}
