113	/// The code on npm's `npm ERR! code X` or `npm error code X` stderr line; npm 8 prints no JSON body.
114	pub(super) fn npm_stderr_code(stderr: &str) -> Option<String> {
115	    stderr.lines().find_map(|line| {
116	        let rest = line
117	            .strip_prefix("npm ERR! ")
118	            .or_else(|| line.strip_prefix("npm error "))?;
119	        rest.strip_prefix("code ").map(|code| code.trim().to_owned())
120	    })
