178	        let args: Vec<&str> = args.iter().map(String::as_str).collect();
179	        let workspace_dir = crate::workspace_owner::npm_workspace_dir(context.root(), &operation.package_dir)?;
180	        let output = match run_observation(
181	            context.runner(),
182	            programs::NPM,
183	            &args,
